var EXTRA=[{"dot": "gray", "j": "Arthroscopy", "h": "Menisco laterale ipermobile: l'editoriale dice di riparare, non resecare", "v": "Commento di Super, Murray, Tollefson e LaPrade: l'istologia dei fascicoli non basta a scegliere la tecnica, la priorità è ripristinare l'anatomia nativa senza ipervincolare lo iato popliteo; è un'opinione di esperti, non uno studio.", "pmid": "42859895", "doi": "10.1002/arj.70655", "temi": ["menisco laterale", "riparazione", "iato popliteo"]}, {"dot": "gray", "j": "Knee Surg Sports Traumatol Arthrosc", "h": "Protesi robotica: il fenotipo coronale spiega poco dell'equilibrio finale", "v": "Studio retrospettivo del gruppo HSS: allineamento e rimodellamento osseo spiegano in parte il bilanciamento iniziale e quasi nulla quello finale; gli autori ne ricavano che serve valutare direttamente in sala.", "pmid": "42868008", "doi": "10.1002/ksa.70648", "temi": ["TKA robotica", "bilanciamento", "fenotipo coronale"]}, {"dot": "gray", "j": "J Robot Surg", "h": "TKA robotica funzionale nei varo: più rotazione femorale dove il mediale è stretto", "v": "Osservazione di un solo chirurgo: la rotazione femorale scelta segue la tensione mediale in flessione, con rilasci quasi sempre lievi; gli autori precisano che l'equazione descrive le decisioni di un chirurgo e non è una regola validata.", "pmid": "42860454", "doi": "10.1007/s11701-026-04037-6", "temi": ["TKA robotica", "allineamento funzionale", "rotazione femorale"]}, {"dot": "gray", "j": "Arthrosc Tech", "h": "Rotula alta nell'adolescente: imbricazione del tendine rotuleo a doppia fila", "v": "Nota tecnica senza pazienti: imbricazione senza sezione del tendine come alternativa alla distalizzazione della tuberosità tibiale, per evitare il rischio sulle cartilagini di crescita; nessun dato clinico.", "pmid": "42857235", "doi": "10.1002/atn2.70288", "temi": ["rotula alta", "instabilità rotulea", "scheletricamente immaturo"]}, {"dot": "gray", "j": "J Pediatr Soc North Am", "h": "Legamenti del ginocchio pediatrico: misure RM di riferimento per tutte le età", "v": "Studio retrospettivo su risonanze: le dimensioni di LCA, LCP e collaterali crescono con la statura più che con l'età anagrafica; utile come riferimento per leggere le RM del paziente in crescita.", "pmid": "42861031", "doi": "10.1016/j.jposna.2026.100455", "temi": ["LCA adolescente", "legamenti pediatrici", "risonanza"]}, {"dot": "gray", "j": "J Exp Orthop", "h": "Ginocchio rivolto all'interno: un angolo TC per la torsione dei pazienti rotulei", "v": "Protocollo TC funzionale con i piedi nella posizione del passo: l'angolo proposto è molto riproducibile fra osservatori, ma mancano valori normali e soglie cliniche.", "pmid": "42861179", "doi": "10.1002/jeo2.70938", "temi": ["instabilità rotulea", "torsione", "TC"]}, {"dot": "gray", "j": "Arthrosc Sports Med Rehabil", "h": "Condroplastica rotulea isolata: miglioramento precoce dei punteggi riferiti", "v": "Serie di casi da un solo registro chirurgico: i punteggi migliorano già nei primi mesi e restano, nessun fattore preoperatorio prevede l'esito; è una serie senza confronto.", "pmid": "42865974", "doi": "10.1002/ars2.70095", "temi": ["condromalacia rotulea", "condroplastica", "PRO"]}, {"dot": "gray", "j": "J Pediatr Orthop", "h": "Trisomia 21 e instabilità rotulea: prevalenza più bassa del temuto, più interventi", "v": "Analisi su una rete di cartelle cliniche americane: l'instabilità rotulea è meno frequente di quanto riportato in passato nei bambini con trisomia 21, ma chi ne è colpito viene operato più spesso dei controlli abbinati.", "pmid": "42860872", "doi": "10.1097/BPO.0000000000003499", "temi": ["instabilità rotulea", "trisomia 21", "pediatria"]}, {"dot": "gray", "j": "Front Surg", "h": "UKA a piatto mobile o fisso: esiti simili a breve termine, differenze nel costo", "v": "Retrospettivo di un solo chirurgo, controllo a pochi mesi: stessi miglioramenti nei punteggi, lieve vantaggio di correzione e mobilità con il piatto mobile, costo di degenza minore con il fisso; follow-up troppo breve per concludere.", "pmid": "42865442", "doi": "10.3389/fsurg.2026.1746302", "temi": ["UKA", "piatto mobile", "costi"]}, {"dot": "gray", "j": "J Orthop Res", "h": "Estrusione meniscale mappata su tutta la circonferenza con la RM 3D", "v": "Metodo di misura radiale su risonanza ad alta risoluzione, molto riproducibile fra lettori in un piccolo gruppo; offre una mappa regionale dell'estrusione, utile per studi futuri più che per la clinica di oggi.", "pmid": "42864603", "doi": "10.1002/jor.70291", "temi": ["estrusione meniscale", "risonanza 3D", "misura"]}, {"dot": "gray", "j": "Arthroscopy", "h": "Lateralizzazione rotulea: il gruppo di controllo è il vero problema dell'imaging", "v": "Commento sulle misure alternative alla distanza tuberosità tibiale-gola nella displasia trocleare: per valutarne l'utilità serve un gruppo di controllo difficile da ottenere.", "pmid": "42859415", "doi": "10.1002/arj.70657", "temi": ["lateralizzazione rotulea", "displasia trocleare", "imaging"]}, {"dot": "gray", "j": "J Arthroplasty", "h": "Paura e recupero dopo protesi d'anca e di ginocchio: una griglia a quattro dimensioni", "v": "Revisione sistematica che propone un quadro (fiducia nelle cadute, evitamento, ansia, paura della recidiva) per riconoscere le barriere psicologiche; chinesiofobia e catastrofizzazione del dolore si associano a esiti peggiori; l'abstract non riporta numeri e il quadro è una proposta, non validata. Riguarda anca e ginocchio insieme.", "pmid": "42855016", "doi": "10.1016/j.arth.2026.10.003", "temi": ["protesi", "chinesiofobia", "recupero"]}];
var SCOPERTE=[{"t": "Un robot per la protesi di ginocchio che segue l'osso mentre si muove, senza fissare la gamba", "v": "Ingegneria cinese (MicroPort): il braccio robotico segue in tempo reale i piccoli movimenti dell'osso durante la resezione, per evitare i fissatori dell'arto, che secondo gli autori aumentano l'errore di taglio e il tempo operatorio. Vale la deviazione perché mostra dove va la robotica fuori dal sistema che usi; è una descrizione tecnologica di un'azienda, senza dati clinici nell'abstract.", "pmid": "42865046", "doi": "10.12455/j.issn.1671-7104.250661", "temi": ["robotica", "TKA", "Cina"]}, {"t": "L'apprendimento automatico dice che cosa trattiene il paziente in ospedale dopo una protesi", "v": "Uno studio inglese su circa tremila pazienti con protesi d'anca e di ginocchio in un percorso di recupero accelerato uguale per tutti: il fattore dominante per la dimissione in giornata è il tempo alla prima mobilizzazione, potenzialmente modificabile ma da confermare in uno studio prospettico. Vale la deviazione per l'organizzazione sanitaria: un modello per interrogare il percorso, non il paziente.", "pmid": "42864658", "doi": "10.1186/s42836-026-00435-1", "temi": ["intelligenza artificiale", "recupero accelerato", "organizzazione"]}, {"t": "Una matrice ricavata da un vaso decellularizzato per ricostruire il menisco, provata nel coniglio", "v": "Ingegneria tissutale (Huangshi, Cina): la matrice conserva collagene e glicosaminoglicani, non è citotossica e, a tre mesi nel coniglio, la risonanza mostra nuovo tessuto meniscale e cartilagine preservata. Vale la deviazione come direzione per i sostituti meniscali; è un modello animale, lontano dall'uomo.", "pmid": "42857962", "doi": "10.1177/10225536261494292", "temi": ["menisco", "ingegneria tissutale", "scaffold"]}];
var SOC={"1": {"video": "Sutura della radice del menisco: aprire molto il legamento collaterale per lavorare meglio non ha lasciato lassità rilevante a sei mesi. Lo mostra una serie di 21 operati di Chicago (Am J Sports Med, ottobre 2026).\n\nIl ginocchio operato si apriva in valgo in media 1,2 millimetri più del sano, contro una soglia di 3,2 millimetri oltre la quale la lassità conta.\n\nIl limite: pochi casi, nessun confronto con un gesto più leggero, nessun dato sui sintomi né sulla guarigione del menisco.\nFonte: PubMed, PMID 42865127.", "linkedin": "Rifissazione della radice posteriore del menisco mediale con pie-crusting spinto del collaterale mediale: a circa 6 mesi la differenza di apertura in valgo con il lato sano è di 1,21 ± 1,07 mm (IC 95% 0,73-1,70), sotto la soglia di 3,2 mm di lassità clinicamente rilevante (p<0,001). Serie di casi retrospettiva, 21 pazienti, Rush University, Am J Sports Med, ottobre 2026.\n\nIl pie-crusting era portato a rilascio udibile e palpabile con apertura mediale di almeno 6 mm in artroscopia; radiografie da stress in valgo a 20° di flessione, controlaterale come controllo.\n\nLimiti: livello IV, nessun gruppo con pie-crusting meno spinto, una sola misura radiografica, nessun esito clinico né guarigione della radice riportati nell'abstract.\nFonte: PubMed, PMID 42865127.", "instagram": "Sutura della radice del menisco: il legamento collaterale, aperto con piccole punture per vedere meglio, resta stabile.\n21 operati: a circa sei mesi, 1,2 mm di apertura in più rispetto al ginocchio sano.\nSoglia di instabilità: 3,2 mm.\nStudio piccolo, senza dati sui sintomi.\nFonte: PubMed, PMID 42865127.", "pazienti": "Sutura della radice del menisco: il legamento di lato resta stabile dopo il gesto usato per vedere meglio.\n\nIn 21 persone operate, dopo circa sei mesi il ginocchio operato si apriva in media poco più di un millimetro in più rispetto a quello sano, meno della soglia che indica instabilità.\n\nStudio piccolo, che non valuta i sintomi: la decisione si prende con il chirurgo.\nFonte: PubMed, PMID 42865127."}};
var SOCV={"1": {"video": {"chir": ["Rifissazione della radice posteriore del menisco mediale con pie-crusting spinto del collaterale mediale: che cosa resta del legamento? Serie di casi di Chicago, American Journal of Sports Medicine, ottobre 2026, ventuno pazienti, livello di evidenza quattro. Il pie-crusting è stato portato a un rilascio udibile e palpabile, con apertura mediale di almeno sei millimetri in artroscopia.", "Alle radiografie da stress in valgo a venti gradi di flessione, a circa sei mesi, l'apertura mediale era 7,84 millimetri nel ginocchio operato e 6,62 nel controlaterale. La differenza media è 1,21 millimetri, intervallo di confidenza al novantacinque per cento da 0,73 a 1,70, contro una soglia di 3,2 millimetri per la lassità clinicamente rilevante.", "I limiti contano. Ventuno casi, nessun gruppo con pie-crusting meno spinto, una sola misura radiografica, nessun esito clinico e nessun dato sulla guarigione della radice nell'abstract. Il lavoro dice che il gesto non lascia lassità oltre soglia a sei mesi; non dice che sia privo di effetti su altro.\nFonte: PubMed, PMID 42865127."], "misto": ["Sutura della radice del menisco interno: per lavorare meglio si fanno piccole punture nel legamento collaterale. Quanto lo indeboliscono? Ce lo dice una serie di ventuno operati di Chicago, pubblicata a ottobre 2026 sull'American Journal of Sports Medicine.", "Circa sei mesi dopo, con una radiografia sotto sforzo in valgo, il ginocchio operato si apriva in media 1,2 millimetri più del ginocchio sano. Per avere un'instabilità che conta, gli autori indicano una differenza di 3,2 millimetri: qui si resta sotto, con un margine ampio.", "Il limite: sono pochi casi, misurati una volta sola, senza un gruppo con punture più leggere. Lo studio non dice come stessero i sintomi né se il menisco fosse guarito. Dice soltanto che il legamento, in media, è rimasto stabile.\nFonte: PubMed, PMID 42865127."], "pazienti": ["Nella sutura della radice del menisco, il chirurgo può fare piccole punture nel legamento di lato per vedere meglio. Una domanda possibile è se questo renda il ginocchio meno stabile.", "In uno studio su ventuno persone operate, dopo circa sei mesi il ginocchio operato si apriva solo poco più di un millimetro in più rispetto a quello sano, quando la differenza che conta è di oltre tre millimetri.", "È uno studio piccolo, che misura la stabilità ma non i sintomi. Se hai domande sul tuo caso, il momento giusto è il colloquio con il chirurgo.\nFonte: PubMed, PMID 42865127."]}, "linkedin": {"chir": ["Rifissazione della radice posteriore del menisco mediale con pie-crusting spinto del collaterale mediale: a circa 6 mesi la differenza di apertura in valgo con il lato sano è di 1,21 ± 1,07 mm (IC 95% 0,73-1,70), sotto la soglia di 3,2 mm (p<0,001). Serie di casi, 21 pazienti, Rush University, Am J Sports Med, ottobre 2026.", "Pie-crusting portato a rilascio udibile e palpabile con apertura mediale di almeno 6 mm in artroscopia; radiografie da stress in valgo a 20° di flessione, controlaterale come controllo interno; campione calcolato a priori su una soglia di 3,2 mm.", "Limiti: livello IV, nessun gruppo con pie-crusting meno spinto, una sola misura radiografica, nessun esito clinico né dato sulla guarigione della radice nell'abstract.\nFonte: PubMed, PMID 42865127."], "misto": ["Sutura della radice del menisco: aprire il legamento collaterale con piccole punture per lavorare meglio non ha lasciato instabilità rilevante a sei mesi. Serie di 21 operati, Am J Sports Med, ottobre 2026.", "Alla radiografia sotto sforzo il ginocchio operato si apriva in media 1,21 mm più del sano (IC 95% 0,73-1,70), contro una soglia di 3,2 mm per la lassità clinicamente rilevante.", "Limite: pochi casi, una sola misura, nessun confronto con un gesto più leggero, nessun dato sui sintomi.\nFonte: PubMed, PMID 42865127."], "pazienti": ["Sutura della radice del menisco: il legamento di lato resta stabile dopo il gesto usato per vedere meglio.", "In 21 persone operate, dopo circa sei mesi il ginocchio operato si apriva solo poco più di un millimetro in più rispetto al sano; la soglia di instabilità è sopra i tre millimetri.", "Studio piccolo, che non valuta i sintomi: la decisione si prende con il chirurgo.\nFonte: PubMed, PMID 42865127."]}, "instagram": {"chir": ["Radice posteriore del menisco mediale, pie-crusting spinto.", "Apertura in valgo +1,21 mm (IC 95% 0,73-1,70) contro soglia di 3,2 mm.", "21 casi, livello IV, nessun esito clinico.\nFonte: PubMed, PMID 42865127."], "misto": ["Sutura della radice del menisco.", "Legamento di lato aperto con punture: +1,2 mm rispetto al sano.", "Soglia di instabilità 3,2 mm. Pochi casi.\nFonte: PubMed, PMID 42865127."], "pazienti": ["Sutura della radice del menisco.", "Il legamento di lato resta stabile: poco più di 1 mm di differenza.", "Studio piccolo: se ne parla con il chirurgo.\nFonte: PubMed, PMID 42865127."]}, "reel": {"chir": ["Radice del menisco mediale, pie-crusting spinto.", "A sei mesi, apertura in valgo +1,21 mm contro soglia di 3,2 mm.", "Ventuno casi, nessun esito clinico, livello IV.\nFonte: PubMed, PMID 42865127."], "misto": ["Sutura della radice del menisco.", "Il legamento di lato, aperto con punture, resta stabile: 1,2 mm contro 3,2 di soglia.", "Pochi casi, nessun dato sui sintomi.\nFonte: PubMed, PMID 42865127."], "pazienti": ["Sutura della radice del menisco.", "Il legamento di lato resta stabile.", "Studio piccolo: se ne parla con il chirurgo.\nFonte: PubMed, PMID 42865127."]}}};
var TAGS={"1": {"linkedin": "#Ortopedia #Menisco #ChirurgiaDelGinocchio", "instagram": "#ortopedia #ginocchio #menisco #radicemeniscale #suturameniscale #artroscopia #chirurgiaortopedica #medicinadellosport #ortopediaticino #medicinabasatasulleprove", "kw": "menisco, radice meniscale, sutura del menisco, artroscopia del ginocchio"}};
var NLB={"1": {"prof": ["Radice mediale: dopo pie-crusting spinto del collaterale la lassità in valgo è di 1,2 mm", "Serie di casi retrospettiva (Am J Sports Med, ottobre 2026), 21 rifissazioni isolate della radice posteriore del menisco mediale con pie-crusting percutaneo ad alto grado: alle radiografie da stress in valgo a circa 6 mesi la differenza con il lato sano è di 1,21 ± 1,07 mm (IC 95% 0,73-1,70), sotto la soglia di 3,2 mm di lassità clinicamente rilevante (p<0,001).", "Nota critica: 21 casi senza confronto con un pie-crusting meno spinto, una sola misura radiografica a 6 mesi, nessun esito clinico né dato sulla guarigione della radice nell'abstract."], "mix": ["Sutura della radice del menisco: aprire molto il collaterale non ha dato instabilità rilevante", "In 21 persone operate di sutura della radice del menisco interno, con il legamento collaterale mediale «aperto» con piccole punture per lavorare meglio, circa sei mesi dopo la radiografia sotto sforzo mostrava in media un millimetro e due decimi di apertura in più rispetto al ginocchio sano, molto meno dei tre millimetri e due decimi oltre i quali si parla di instabilità.", "Nota sul limite: sono pochi casi, senza un gruppo con punture più leggere, misurati una volta sola; lo studio non dice come siano andati i sintomi né se il menisco sia guarito."], "paz": ["Sutura della radice del menisco: il legamento di lato resta stabile dopo il gesto usato per vedere meglio", "In uno studio su 21 persone operate di sutura della radice del menisco interno, il legamento collaterale è stato «allentato» con piccole punture per lavorare meglio. Dopo circa sei mesi il ginocchio operato si apriva in media poco più di un millimetro in più rispetto a quello sano, una differenza che gli autori considerano inferiore a quella che causa instabilità.", "Lo studio è piccolo e non valuta i sintomi: ciò che conta per ciascuno si decide con il chirurgo."], "kw": "menisco, radice meniscale, sutura del menisco, legamento collaterale mediale"}, "2": {"prof": ["Dopo LCA le atlete hanno odds di rientro ad alto rischio pari a 0,47 volte quelle degli atleti", "Analisi secondaria di un RCT (Sports Health, ottobre 2026), 500 operati di LCA con hamstring, con o senza tenodesi laterale, in sport ad alto rischio: tornano a qualsiasi sport l'86,5%, a uno sport ad alto rischio il 76,5%, a sport e livello pre-infortunio il 45,5%. Atlete contro atleti nel rientro ad alto rischio: OR 0,47 (IC 95% 0,29-0,76).", "Nota critica: analisi secondaria non disegnata per questa domanda, innesto hamstring e non retto femorale, odds ratio che con eventi frequenti sovrastima la differenza di probabilità, stime dei predittori non riportate nell'abstract."], "mix": ["Dopo la ricostruzione del crociato, le donne tornano allo sport ad alto rischio meno degli uomini", "Su 500 persone operate di crociato anteriore che praticavano sport con salti e cambi di direzione, l'86,5% è tornato a fare almeno uno sport, il 76,5% a uno sport ad alto rischio e solo il 45,5% allo stesso sport e allo stesso livello di prima. Le donne hanno avuto una probabilità di tornare a sport ad alto rischio più bassa, con un rapporto di 0,47 rispetto agli uomini; nelle donne hanno aiutato la fiducia nel ginocchio, un intervento non tardivo e un ginocchio stabile.", "Nota sul limite: è l'analisi di un trial pensato per un'altra domanda, con un tendine (hamstring) diverso dal retto femorale; mostra un'associazione e non ne spiega il perché."], "paz": ["Dopo l'intervento al crociato, tornare allo sport di prima non è scontato, soprattutto per le donne", "In uno studio su 500 persone operate di legamento crociato anteriore, quasi nove su dieci sono tornate a fare sport, ma meno della metà è tornata allo stesso sport e allo stesso livello di prima. Le donne sono tornate agli sport con salti e cambi di direzione meno degli uomini. Una buona fiducia nel ginocchio e un intervento non troppo tardivo sono andati insieme a un rientro più probabile.", "Lo studio descrive gruppi di persone, non prevede che cosa accadrà a ciascuno: il percorso si costruisce con il chirurgo e con il fisioterapista."], "kw": "legamento crociato anteriore, ritorno allo sport, donne e crociato, riabilitazione"}, "3": {"prof": ["LCA nel calcio svedese: rientro in partita nel 58,5%, ma dopo il rientro la carriera è breve", "Coorte nazionale (Sports Med, ottobre 2026), 10.836 calciatori operati di LCA primario nel 2014-2023: rientro in partita ufficiale nel 58,5% (dal 90,4% al massimo livello al 35,9% al livello amatoriale); dopo il rientro mediana di 31 partite (IQR 11-70) in tre stagioni (IQR 2-5), con differenze per sesso (33 contro 29 partite, p=0,017) e per livello.", "Nota critica: il rientro è definito dalla comparsa in una partita, non dalla prestazione; innesto e tecnica non sono riportati nell'abstract; intervalli di confidenza assenti e nessun aggiustamento per confondenti dichiarato."], "mix": ["Crociato e calcio: più della metà torna in partita, ma poi si gioca meno di quanto ci si aspetti", "In Svezia, su oltre diecimila calciatori operati di crociato anteriore in dieci anni, il 58,5% è tornato a giocare almeno una partita ufficiale; la quota va dal 90,4% ai massimi livelli al 35,9% tra i dilettanti. Chi è tornato ha giocato in mediana 31 partite in tre stagioni: molte di più ai massimi livelli, e un po' di più gli uomini delle donne.", "Nota sul limite: il dato non dice perché si smetta di giocare, che può essere una scelta o un altro infortunio, e non distingue il tipo di intervento."], "paz": ["Crociato e calcio: tornare in campo è comune, ma restarci a lungo dipende dal livello di partenza", "In uno studio svedese su oltre diecimila calciatori operati di legamento crociato anteriore, circa sei su dieci sono tornati a giocare una partita ufficiale; tra i giocatori di vertice quasi tutti, tra i dilettanti circa uno su tre. Dopo il rientro il numero di partite giocate è stato spesso limitato, e più alto per chi giocava a livelli più alti.", "Sono dati su gruppi: non dicono che cosa accadrà a una singola persona e non spiegano perché alcuni smettano."], "kw": "legamento crociato anteriore, calcio, ritorno in campo, carriera sportiva"}, "4": {"prof": ["Menisco laterale ipermobile: punteggio a sei variabili con AUC 0,902, validato solo internamente", "Coorte diagnostica retrospettiva multicentrica (J Orthop Sci, ottobre 2026), 150 pazienti con sintomi laterali persistenti e riferimento artroscopico: il punteggio da 0 a 12 con sei predittori (discordanza RM-clinica, scatto doloroso, cedimento posterolaterale, dolore in flessione profonda, attenuazione del fascicolo popliteomeniscale, sport con rotazioni) ha AUC apparente 0,902 (IC 95% 0,86-0,96), sensibilità 88% e specificità 86%.", "Nota critica: validazione solo interna in pazienti già inviati ad artroscopia, tre gruppi esattamente da 50 in una coorte dichiarata consecutiva, valori predittivi in ambulatorio ignoti."], "mix": ["Menisco laterale ipermobile: un punteggio aiuta a sospettarlo quando la risonanza non lo mostra", "In 150 pazienti con dolore laterale persistente operati in artroscopia, un punteggio basato su sei elementi, tra cui il contrasto fra sintomi e risonanza, lo scatto doloroso in rotazione, il cedimento sul lato esterno e il dolore in flessione profonda, ha riconosciuto il menisco laterale troppo mobile con buona accuratezza (sensibilità 88%, specificità 86%).", "Nota sul limite: il punteggio è stato provato solo sugli stessi pazienti con cui è stato costruito, quindi serve una conferma su altri gruppi prima di usarlo nella pratica."], "paz": ["Dolore esterno al ginocchio: un punteggio può aiutare a riconoscere un menisco troppo mobile", "In uno studio su 150 persone con dolore persistente sul lato esterno del ginocchio, un punteggio composto da sei elementi, come lo scatto doloroso nei movimenti di rotazione e la sensazione di cedimento, ha aiutato a distinguere chi aveva un menisco esterno troppo mobile. Il punteggio è stato provato solo sugli stessi pazienti con cui è stato costruito.", "È uno strumento ancora da confermare: la diagnosi la fa il medico visitando e valutando gli esami."], "kw": "menisco laterale, dolore esterno al ginocchio, scatto del ginocchio, instabilità del menisco"}, "5": {"prof": ["Forza del quadricipite dopo LCA: nel 51% debole da entrambi i lati, nessun legame con KOOS e T1ρ", "Studio longitudinale (Med Sci Sports Exerc, ottobre 2026), 59 operati di LCA con forza isometrica bilaterale prima dell'intervento e a 4, 6 e 12 mesi: tre traiettorie, debole da entrambi i lati 51%, forte da entrambi 38%, operato forte e controlaterale debole 12%. Meniscectomia mediale associata alla traiettoria debole (p<0,001; probabilità 0,86), Tegner pre-infortunio più basso (p=0,01); nessuna associazione con KOOS a 12 mesi né con T1ρ cartilagineo.", "Nota critica: 59 pazienti e un gruppo di circa 7, quindi l'assenza di associazione con gli esiti non è prova di equivalenza; innesto e riabilitazione non riportati nell'abstract, intervalli di confidenza assenti."], "mix": ["Dopo il crociato la coscia sana perde spesso forza: il confronto con quel lato va letto con cautela", "In 59 persone operate di crociato anteriore, seguite fino a un anno, la forza del quadricipite è stata misurata su entrambe le gambe. Nel 51% è rimasta bassa su entrambi i lati, con calo anche della gamba non operata; nel 38% è stata alta su entrambi. La meniscectomia mediale e una minore attività prima dell'infortunio si sono associate a un recupero peggiore, mentre la forza non ha mostrato legami con il punteggio KOOS né con la cartilagine a un anno.", "Nota sul limite: il gruppo è piccolo, quindi l'assenza di legami con gli esiti non significa che non esistano; il tipo di tendine e la riabilitazione non sono indicati."], "paz": ["Dopo il crociato, la forza della coscia si misura su entrambe le gambe, non solo su quella operata", "In uno studio su 59 persone operate di legamento crociato anteriore, circa una su due aveva una coscia debole su entrambi i lati già prima dell'intervento e non ha recuperato la forza della gamba operata entro un anno. Chi aveva una forza migliore all'inizio l'ha recuperata più spesso. Nello studio la forza non ha mostrato legami con il punteggio di benessere del ginocchio a un anno.", "Il gruppo è piccolo: il risultato è un'indicazione, non una regola per ciascuno."], "kw": "legamento crociato anteriore, forza del quadricipite, riabilitazione, recupero dopo crociato"}, "6": {"prof": ["Mini-impianti Episealer nel femore distale: sopravvivenza a 60 mesi 88,1% con uno, 83,4% con due", "Serie retrospettiva su dati prospettici (J ISAKOS, ottobre 2026), 93 pazienti, un impianto (45) o due (48), follow-up medio 38 mesi: KOOS sintomi da 48,7 ± 17,9 a 74,3 ± 21,6 con un impianto e da 44,7 ± 15,0 a 66,0 ± 24,8 con due (p<0,001); sopravvivenza di Kaplan-Meier a 60 mesi 88,1% (21 a rischio) e 83,4% (27 a rischio).", "Nota critica: nessun gruppo di confronto, IC non riportati e solo 21 e 27 pazienti a rischio a cinque anni; è sostituzione parziale con metallo, non cartilagine biologica."], "mix": ["Mini-impianto metallico su misura per la cartilagine del femore: risultati a circa tre anni", "In 93 pazienti di mezza età con piccole lesioni di cartilagine e osso nel femore, in cui la riparazione biologica era fallita o improbabile, uno o due mini-impianti metallici costruiti su misura hanno migliorato sintomi e dolore a circa tre anni. A cinque anni l'impianto era ancora in sede nell'88,1% di chi ne aveva uno e nell'83,4% di chi ne aveva due.", "Nota sul limite: non c'è un gruppo di confronto, e a cinque anni i pazienti seguiti erano poche decine; l'impianto sostituisce una parte dell'articolazione e non rigenera la cartilagine."], "paz": ["Cartilagine del femore: un mini-impianto su misura quando la riparazione biologica non è possibile", "In uno studio su 93 persone di mezza età con una o due piccole lesioni della cartilagine del femore, un mini-impianto metallico fatto su misura ha ridotto i sintomi e il dolore a circa tre anni dall'intervento. Dopo cinque anni la grande maggioranza degli impianti era ancora al suo posto.", "Non c'è un gruppo di confronto e il numero di persone seguite a cinque anni è piccolo: la scelta del trattamento dipende dal singolo caso."], "kw": "cartilagine del ginocchio, lesione condrale, mini-impianto, femore"}, "7": {"prof": ["Cartilagine ialina ingegnerizzata decellularizzata (dLhCG): primo impiego sull'uomo, 17 pazienti", "Studio prospettivo esplorativo first-in-human (Adv Sci, ottobre 2026), 17 pazienti con difetti condrali del ginocchio Outerbridge III/IV: integrazione stabile fino a 18 mesi, miglioramento significativo di punteggi clinici e MOCART, rapporto T2 tra tessuto riparato e cartilagine sana vicino a 1, nessun evento avverso clinico grave e anomalie asintomatiche alla RM, fra cui edema osseo.", "Nota critica: 17 pazienti, nessun controllo, 18 mesi di osservazione, nessun valore numerico nell'abstract; il rapporto T2 è un surrogato di imaging e non un esito riferito dal paziente."], "mix": ["Cartilagine del ginocchio: un innesto ingegnerizzato provato per la prima volta su 17 persone", "In 17 persone con danni profondi della cartilagine del ginocchio è stato impiantato un innesto di cartilagine costruito in laboratorio e privato delle sue cellule. Fino a 18 mesi l'innesto è rimasto integrato, i punteggi sono migliorati e la risonanza ha mostrato un tessuto simile alla cartilagine sana, senza eventi avversi gravi; in alcuni casi sono comparse alterazioni senza sintomi, come edema dell'osso.", "Nota sul limite: è un primo studio esplorativo, senza gruppo di confronto e con pochi pazienti; non permette di dire se faccia meglio delle tecniche già in uso."], "paz": ["Cartilagine del ginocchio: un innesto costruito in laboratorio è stato provato su 17 persone", "In uno studio iniziale su 17 persone con un danno profondo della cartilagine del ginocchio, un innesto prodotto in laboratorio è rimasto ben inserito fino a 18 mesi, e i punteggi clinici sono migliorati. Non sono stati segnalati eventi avversi gravi. Si tratta di una prima verifica: servono studi più ampi e con un confronto.", "Questo trattamento è ancora in fase di studio."], "kw": "cartilagine del ginocchio, difetto condrale, innesto di cartilagine, ricerca clinica"}, "8": {"prof": ["TKA e risurfacciamento rotuleo di routine: 22 lesioni peripatellari operate su 2508, 0 su 875", "Coorte retrospettiva di una pratica (Arthroplast Today, ottobre 2026), 3383 protesi totali primarie: lesioni peripatellari operate 22/2508 (0,88%; IC 95% 0,55-1,33) con rotula risurfacciata contro 0/875 (IC 95% 0-0,42) senza; OR di Firth 15,85 (IC 95% 2,20-2013,54).", "Nota critica: non randomizzato, evento raro, intervallo dell'OR enorme, esito limitato agli interventi peripatellari e non alle revisioni complessive; follow-up non riportato."], "mix": ["Protesi totale: le lesioni attorno alla rotula sono comparse solo dove la rotula era risurfacciata", "In 3383 protesi totali di ginocchio di un'unica pratica, le 22 lesioni intorno alla rotula che hanno richiesto un nuovo intervento (0,88%) sono comparse tutte nel gruppo con la rotula risurfacciata, e nessuna nel gruppo senza risurfacciamento (875 ginocchia). L'evento è raro e il confronto non permette di stabilirne l'entità con precisione.", "Nota sul limite: i gruppi non sono stati formati per sorteggio e lo studio non valuta le revisioni complessive né il dolore anteriore."], "paz": ["Protesi di ginocchio: complicazioni intorno alla rotula rare, osservate solo con la rotula rivestita", "In uno studio su 3383 protesi di ginocchio operate in un'unica pratica, i problemi intorno alla rotula che hanno richiesto un nuovo intervento sono stati meno di uno su cento e si sono verificati solo nelle persone in cui la rotula era stata rivestita con una componente protesica. Nessun problema di questo tipo è stato operato nel gruppo senza rivestimento.", "Sono dati di un solo centro e non permettono di dire quale scelta sia migliore per ciascuno: se ne parla con il chirurgo."], "kw": "protesi di ginocchio, rotula, complicazioni protesi, chirurgia protesica"}, "9": {"prof": ["Due protesi totali a 15 anni: esiti uguali, ma più dolore anteriore e artrosi rotulea con Kinemax", "Follow-up minimo di 15 anni di un RCT (Bone Jt Open, ottobre 2026), Kinemax contro Triathlon: nove revisioni, nessuna differenza (p=0,721); 61 valutati funzionalmente senza differenze in OKS, FJS, EQ-5D (p≥0,170). Con Kinemax dolore anteriore più frequente (OR 3,2; p=0,037), linee radiotrasparenti tibiali in zona 1 (OR 12,1; IC 95% 2,6-57,6) e artrosi femororotulea grave (OR 5,1; IC 95% 1,4-18,4).", "Nota critica: solo 61 valutati funzionalmente, età media 80 anni, nove revisioni totali con ripartizione non riportata, IC larghi; nessuna prova di equivalenza."], "mix": ["Due protesi totali a confronto dopo 15 anni: stessi risultati riferiti, ma una dà più dolore davanti", "In uno studio randomizzato seguito per almeno 15 anni, due modelli di protesi totale di ginocchio hanno dato punteggi di funzione, qualità di vita e soddisfazione sovrapponibili, con nove revisioni in tutto e nessuna differenza fra i gruppi. Il modello Kinemax si è associato a più dolore nella parte anteriore del ginocchio e a un'artrosi più grave tra rotula e femore, senza che ciò abbia modificato in modo evidente gli esiti.", "Nota sul limite: i pazienti valutati a 15 anni sono 61, con età media di 80 anni, quindi il campione è quello dei sopravvissuti e non esclude differenze di entità moderata."], "paz": ["Protesi di ginocchio dopo 15 anni: due modelli con risultati simili, uno con più dolore davanti", "In uno studio che ha seguito per almeno 15 anni persone operate di protesi totale di ginocchio con due modelli diversi, i risultati su funzione, qualità di vita e soddisfazione sono stati simili, e le revisioni sono state nove in tutto. Con uno dei due modelli il dolore nella parte anteriore del ginocchio è stato più frequente.", "Metà dei partecipanti era deceduta nel frattempo, per cui il confronto riguarda i sopravvissuti: la scelta della protesi si discute con il chirurgo."], "kw": "protesi totale di ginocchio, risultati a lungo termine, dolore anteriore, rotula"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"green",sec:"res",j:"Am J Sports Med",h:"Radice meniscale: il pie-crusting spinto del collaterale mediale non lascia lassità valgo rilevante",v:"Serie di casi retrospettiva (Rush University, Chicago; livello IV): 21 rifissazioni isolate della radice posteriore del menisco mediale con pie-crusting percutaneo spinto del collaterale mediale (rilascio udibile e palpabile, apertura mediale di almeno 6 mm in artroscopia). Radiografie da stress in valgo a 20° di flessione, in media 5,9 ± 2,0 mesi dopo. Apertura mediale 7,84 ± 1,65 mm nel ginocchio operato contro 6,62 ± 1,37 mm nel controlaterale: differenza 1,21 ± 1,07 mm (IC 95% 0,73-1,70), sotto la soglia di 3,2 mm di lassità clinicamente rilevante (p<0,001).",ax:"Nishioka, Thamrongskulsiri, Casanova, Ackermann, Morgan, Moews, Vega, Spaan, Chahla",date:"ott 2026",meta:"serie di casi retrospettiva, 21 pazienti, rifissazione della radice mediale con pie-crusting spinto, radiografie da stress a circa 6 mesi · [livello IV]",pmid:'42865127',doi:'10.1177/03635465261492229',journal:"The American journal of sports medicine",authors:"Nishioka T, Thamrongskulsiri N, Casanova F, Ackermann J, Morgan JT, Moews LD, Vega TF, Spaan J, Chahla J",design:"Serie di casi retrospettiva (Rush University Medical Center, Chicago; Chulalongkorn University, Bangkok), livello IV dichiarato: pazienti con rifissazione isolata della radice posteriore del menisco mediale, senza chirurgia legamentosa pregressa, con pie-crusting percutaneo ad alto grado (rilascio udibile e palpabile, apertura mediale di almeno 6 mm sotto visione artroscopica). Radiografie bilaterali da stress in valgo a 20° di flessione a 5,9 ± 2,0 mesi; controlaterale come controllo interno; test a un campione contro la soglia di 3,2 mm, con calcolo a priori del campione (15 pazienti). Solo abstract letto: non risulta testo completo in PMC.",pop:"21 pazienti con rifissazione isolata della radice posteriore del menisco mediale. Età, sesso, tecnica di riparazione, numero di punture, protocollo post-operatorio ed esiti clinici: non riportati nell'abstract.",results:"Apertura mediale 7,84 ± 1,65 mm nel ginocchio operato e 6,62 ± 1,37 mm nel controlaterale; differenza fra i due lati 1,21 ± 1,07 mm (IC 95% 0,73-1,70), inferiore alla soglia di 3,2 mm (p<0,001). Guarigione della radice ed esiti clinici: non riportati nell'abstract.",concl:"Gli autori: il pie-crusting percutaneo ad alto grado, spinto fino a un endpoint intraoperatorio definito, dà piccoli aumenti dell'apertura mediale, sotto le soglie biomeccaniche di instabilità; i dati preliminari suggeriscono migliore visione e strumentazione senza lassità in valgo clinicamente rilevante.",limits:"21 casi, nessun gruppo con pie-crusting a basso grado o senza · una sola misura a circa 6 mesi, radiografica a 20°, nessun esito clinico nell'abstract · la soglia di 3,2 mm viene da dati biomeccanici, non da esiti dei pazienti · lassità a lungo termine e guarigione della radice non studiate · solo abstract letto.",perte:"È la tua chirurgia (rifissazione della radice mediale), e il pie-crusting è il gesto con cui si apre il compartimento mediale per lavorarci. Il dato rassicura sul costo del gesto spinto: dopo circa sei mesi la lassità in valgo resta in media a 1,2 mm dal lato sano, lontana da 3,2 mm. Non dice nulla sulla guarigione della radice né sul lungo termine. Cosa fare: nessun motivo per cambiare gesto; se ti frenava il timore di lassità, ora c'è un dato a favore, piccolo."},
{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Sports Health",h:"Dopo LCA le atlete hanno odds di rientro ad alto rischio dimezzate: OR 0,47",v:"Analisi secondaria di un RCT (livello 1 dichiarato): 500 pazienti operati di LCA con hamstring a singolo fascio, con o senza tenodesi laterale con bendelletta ileotibiale, praticanti prima uno sport ad alto rischio (salti, rotazioni, cambi di direzione). Rientro a qualsiasi sport 86,5%, a uno sport ad alto rischio 76,5%, a sport e livello pre-infortunio solo 45,5%. Atlete contro atleti, rientro ad alto rischio: OR 0,47 (IC 95% 0,29-0,76; p<0,01). Nelle atlete predicono il rientro intervento più precoce, maggiore fiducia nel ginocchio e ginocchio stabile.",ax:"Marmura, Firth, Getgood, Bryant",date:"ott 2026",meta:"analisi secondaria di RCT, 500 pazienti, LCA con hamstring ± tenodesi laterale · [livello 1 dichiarato, analisi secondaria]",pmid:'42865115',doi:'10.1177/19417381261491843',journal:"Sports health",authors:"Marmura H, Firth A, Getgood AM, Bryant DM",design:"Analisi secondaria di un RCT che confronta il LCA con hamstring a singolo fascio con o senza tenodesi extra-articolare laterale con bendelletta ileotibiale; l'abstract non nomina il trial. Inclusi i pazienti che prima dell'infortunio praticavano uno sport ad alto rischio. Tre definizioni di rientro: sport e livello pre-infortunio; qualsiasi sport ad alto rischio; qualsiasi sport. Regressioni logistiche multivariate per i predittori. Solo abstract letto.",pop:"500 pazienti con sport ad alto rischio prima dell'infortunio. Età, quota di donne, tempo al rientro e durata del follow-up: non riportati nell'abstract.",results:"Rientro a qualsiasi sport 86,5%, a uno sport ad alto rischio 76,5%, a sport e livello pre-infortunio 45,5%. Atlete contro atleti, rientro a sport ad alto rischio: OR 0,47 (IC 95% 0,29-0,76; p<0,01). Predittori nelle atlete: intervento più precoce, maggiore fiducia nel ginocchio, ginocchio stabile (stime non riportate nell'abstract).",concl:"Gli autori: le atlete tornano meno dei colleghi dopo il LCA, con la differenza maggiore negli sport ad alto rischio; sono una popolazione bersaglio per interventi che migliorino il rientro, con prontezza psicologica e stabilità del ginocchio come obiettivi.",limits:"Analisi secondaria: il trial non era disegnato per questa domanda · innesto hamstring, non il tuo retto femorale · tipo di sport, livello e modalità di rilevazione del rientro non riportati nell'abstract · odds ratio, non rischio relativo: con rientri frequenti sovrastima la differenza di probabilità · follow-up non riportato.",perte:"Innesto diverso: hamstring, non il tuo retto femorale; e il rinforzo laterale era randomizzato, mentre tu lo fai su tutti. Quello che trasferisce non è il confronto fra innesti ma la dimensione del problema: meno di uno su due torna a sport e livello di prima, e fra le atlete le odds di tornare a sport ad alto rischio sono 0,47 volte quelle degli uomini. Cosa fare: nel colloquio sul rientro, per le atlete, parlare di fiducia nel ginocchio e di tempi dell'intervento; non basta per fissare una soglia."},
{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Sports Med",h:"LCA nel calcio: il 58,5% torna in partita, ma dopo il rientro si gioca poco",v:"Coorte nazionale svedese (Registro dei legamenti del ginocchio collegato al database delle partite della federazione): 10.836 calciatori operati di LCA primario nel 2014-2023. Rientro in partita ufficiale in 6339 (58,5%), dal 90,4% al massimo livello al 35,9% a livello amatoriale (p<0,001). Fra 4749 con follow-up sufficiente: mediana 31 partite (IQR 11-70) in tre stagioni (IQR 2-5); uomini 33 contro 29 partite delle donne (p=0,017) e 4 contro 3 stagioni (p<0,001). Al massimo livello mediana 97 partite (IQR 42-148) in cinque stagioni.",ax:"Sandon, von Essen, Farooq, Forssblad",date:"ott 2026",meta:"coorte nazionale (registro + database delle partite), 10.836 calciatori, LCA primario 2014-2023 · [livello non dichiarato nell'abstract]",pmid:'42867625',doi:'10.1007/s40279-026-02558-6',journal:"Sports medicine (Auckland, N.Z.)",authors:"Sandon A, von Essen C, Farooq A, Forssblad M",design:"Coorte nazionale di un decennio: calciatori operati di LCA primario nel 2014-2023 identificati nel Registro svedese dei legamenti del ginocchio e collegati al database delle partite della federazione calcistica svedese. Rientro = almeno una partita ufficiale dopo l'intervento; la partecipazione dopo il rientro è analizzata solo per chi è tornato entro la stagione 2022 (almeno tre stagioni potenziali). Confronti non parametrici per sesso, età e livello pre-infortunio. Solo abstract letto.",pop:"10.836 calciatori; 6339 tornati in partita; 4749 con follow-up sufficiente per la partecipazione dopo il rientro. Innesto, tecnica, procedure associate, età e quota di donne: non riportati nell'abstract.",results:"Rientro 6339/10.836 (58,5%), dal 90,4% al livello massimo al 35,9% al livello amatoriale (p<0,001). Dopo il rientro, mediana 31 partite (IQR 11-70) in tre stagioni (IQR 2-5). Uomini 33 contro donne 29 partite (p=0,017), 4 contro 3 stagioni (p<0,001). Livello massimo: mediana 97 partite (IQR 42-148) in cinque stagioni (IQR 3-6). Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: la durata della carriera dopo il LCA è maggiore ai livelli pre-infortunio più alti e, in misura minore, negli uomini; il rientro è comune ma la partecipazione a lungo termine è spesso limitata, quindi il solo rientro descrive in modo incompleto la partecipazione dopo il LCA.",limits:"Il rientro è la comparsa in una partita ufficiale: non misura prestazione, né se smettere sia stata una scelta · solo calcio e solo Svezia · nessun confronto con non operati né con altri infortuni · nessun dato su innesto o tecnica nell'abstract · test non parametrici, aggiustamento per confondenti non riportato.",perte:"Fuori dalla tua tecnica (innesto e rinforzo laterale non riportati), ma è il dato da portare al calciatore che chiede se tornerà a giocare: tornare in partita non è tornare a una carriera di durata normale, e il livello di partenza pesa più del sesso. Non cambia l'indicazione; cambia che cosa si dice sul rientro."},
{n:4,mono:"m-gray",dot:"green",sec:"res",j:"J Orthop Sci",h:"Menisco laterale ipermobile: un punteggio a sei variabili riconosce ciò che la RM non vede",v:"Studio diagnostico retrospettivo multicentrico (Ecuador; livello III): 214 pazienti con sintomi laterali persistenti sottoposti ad artroscopia, 150 analizzati (50 con menisco laterale ipermobile isolato, 50 con lesioni strutturali senza ipermobilità, 50 controlli sintomatici). Punteggio da 0 a 12 con sei predittori (discordanza RM-clinica, scatto doloroso in rotazione, cedimento posterolaterale, dolore in flessione profonda, attenuazione del fascicolo popliteomeniscale alla RM, sport con rotazioni): AUC apparente 0,902 (IC 95% 0,86-0,96), corretta per ottimismo 0,890; sensibilità 88%, specificità 86%, LR positivo 6,29 e negativo 0,14. Validazione solo interna.",ax:"Endara Urresta, Barros Castro, Peñaherrera-Carrillo",date:"ott 2026",meta:"studio diagnostico retrospettivo multicentrico, 150 pazienti, menisco laterale ipermobile · [livello III, solo validazione interna]",pmid:'42859119',doi:'10.1016/j.jos.2026.09.016',journal:"Journal of orthopaedic science : official journal of the Japanese Orthopaedic Association",authors:"Endara Urresta F, Barros Castro A, Peñaherrera-Carrillo C",design:"Coorte diagnostica retrospettiva multicentrica: 214 pazienti consecutivi sottoposti ad artroscopia per sintomi laterali persistenti nel 2019-2023, 64 esclusi, 150 analizzati. Riferimento: valutazione artroscopica (50 ipermobilità isolata, 50 lesioni strutturali, 50 controlli sintomatici). Predittori solo preoperatori (dati demografici, clinica, PRO, RM), regressione logistica penalizzata; discriminazione con AUC, calibrazione con pendenza, intercetta e Brier; validazione interna con 1000 ricampionamenti bootstrap. Solo abstract letto.",pop:"150 pazienti, tre gruppi da 50. Età, sesso e tecnica chirurgica: non riportati nell'abstract.",results:"AUC apparente 0,902 (IC 95% 0,86-0,96), corretta per ottimismo 0,890; sensibilità 88%, specificità 86%; LR positivo 6,29, LR negativo 0,14; pendenza di calibrazione 0,97; Brier 0,087.",concl:"Gli autori: il punteggio discrimina bene e in modo stabile in questa coorte sintomatica selezionata; serve validazione esterna prima dell'uso clinico di routine.",limits:"Validazione solo interna, in pazienti già inviati ad artroscopia: i valori predittivi in ambulatorio sono ignoti · esattamente 50 pazienti per gruppo in una coorte dichiarata consecutiva e senza campionamento per quote: da chiarire nel testo completo (mio rilievo) · i predittori includono sintomi e segni che definiscono già il quadro, con rischio di circolarità · solo abstract letto.",perte:"Tocca la chirurgia meniscale che pratichi (riparazione), non una tecnica specifica. Utile come elenco di segni da cercare quando la RM tace e il paziente descrive scatto e cedimento posterolaterale. Non usarlo come regola: nessuna validazione esterna. Nei brevi di oggi c'è l'editoriale di Arthroscopy sullo stesso tema, che chiede di riparare e non resecare."},
{n:5,mono:"m-gray",dot:"green",sec:"res",j:"Med Sci Sports Exerc",h:"Forza del quadricipite dopo LCA: tre traiettorie, nessun legame con KOOS e cartilagine a un anno",v:"Studio longitudinale (UNC Chapel Hill): 59 operati di LCA (58% donne, 21,9 ± 4,7 anni), forza isometrica del quadricipite bilaterale prima dell'intervento e a 4, 6 e 12 mesi. Tre traiettorie combinate: debole da entrambi i lati 51%, forte da entrambi 38%, operato forte e controlaterale debole 12%. Meno attività pre-infortunio (Tegner) associata alla traiettoria debole (p=0,01; probabilità da 0,27 con Tegner 10 a 0,61 con Tegner 0); meniscectomia mediale l'associazione più forte (p<0,001; probabilità 0,86). Nessuna associazione con KOOS a 12 mesi né con la composizione cartilaginea alla RM (T1ρ).",ax:"Franek, Arbeeva, Lee, Lartey, Wang, Hakan Ok, Spang, Ingersoll, Hart, Büttner, Favoreto, Creighton, Kamath, Lisee, Blackburn, Yang, Li, Pietrosimone",date:"ott 2026",meta:"studio longitudinale, 59 operati di LCA, forza del quadricipite a 4-12 mesi, T1ρ cartilagineo · [livello non dichiarato]",pmid:'42868227',doi:'10.1249/MSS.0000000000004187',journal:"Medicine and science in sports and exercise",authors:"Franek M, Arbeeva L, Lee H, Lartey R, Wang X, Hakan Ok A, Spang JT, Ingersoll CD, Hart JM, Büttner C, Favoreto N, Creighton RA, Kamath GM, Lisee C, Blackburn JT, Yang M, Li X, Pietrosimone B",design:"Studio longitudinale (University of North Carolina at Chapel Hill): forza isometrica del quadricipite misurata in entrambi gli arti prima dell'intervento e a 4, 6 e 12 mesi; modelli di traiettoria di gruppo per i due arti, combinati in pattern a doppio arto; regressioni di Dirichlet con dati demografici, PRO (KOOS, Tegner, Marx), chirurgia concomitante e variazioni cartilaginee (T1ρ alla RM, tibiofemorale e femororotulea, prima e a 12 mesi). Solo abstract letto.",pop:"59 partecipanti, 58% donne, età 21,9 ± 4,7 anni, IMC 24,55 ± 3,7 kg/m². Innesto, tecnica e riabilitazione: non riportati nell'abstract.",results:"Traiettorie: debole da entrambi i lati 51%, forte da entrambi 38%, operato forte e controlaterale debole 12%. Tegner pre-infortunio più basso e traiettoria debole: p=0,01 (probabilità da 0,27 a 0,61); meniscectomia mediale: p<0,001 (probabilità 0,86). Nessuna associazione fra traiettorie e KOOS a 12 mesi o T1ρ. Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: chi non recupera la forza dell'arto operato era debole da entrambi i lati già prima dell'intervento, chi aveva più forza bilaterale la recupera; la meniscectomia mediale si associa all'incapacità di recuperare. Nessuna associazione con gli esiti clinici.",limits:"59 pazienti: l'assenza di associazione con KOOS e T1ρ non è assenza di effetto · il gruppo con operato forte e controlaterale debole è di circa 7 pazienti (12% di 59, calcolo mio) · innesto e riabilitazione non descritti nell'abstract · stime e IC delle associazioni non riportati · il controlaterale che perde forza fa muovere il denominatore di ogni indice di simmetria.",perte:"Tocca il nucleo della tua attività (LCA) ma senza innesto dichiarato. Il dato che pesa: nel 51% anche l'arto sano perde forza, quindi un criterio di rientro basato sulla simmetria (LSI) poggia su un denominatore che scende, e questo si somma alla tensione sul criterio di rientro. Con meniscectomia mediale il quadricipite recupera meno (associazione, non causalità). Cosa fare: misurare la forza di entrambi i lati prima dell'intervento, non solo dopo."},
{n:6,mono:"m-gray",dot:"gray",sec:"res",j:"J ISAKOS",h:"Mini-impianti metallici su misura nel femore distale: sopravvivenza 83-88% a cinque anni, senza confronto",v:"Serie retrospettiva su dati prospettici (Greven, Germania; livello III dichiarato): impianto Episealer su misura, uno (45 pazienti) o due (48) per lesioni (osteo)condrali focali del femore distale, follow-up medio 38 mesi. KOOS sintomi da 48,7 ± 17,9 a 74,3 ± 21,6 con un impianto e da 44,7 ± 15,0 a 66,0 ± 24,8 con due; tutte le sottoscale KOOS e il dolore VAS migliorano in entrambi (p<0,001). Sopravvivenza a 60 mesi 88,1% con un impianto (21 a rischio) e 83,4% con due (27 a rischio); IC non riportati.",ax:"Rüter, Kösters, den Toom",date:"ott 2026",meta:"serie retrospettiva su dati prospettici, 93 pazienti (45 + 48), Episealer a medio termine · [livello III dichiarato, nessun controllo]",pmid:'42860156',doi:'10.1016/j.jisako.2026.101234',journal:"Journal of ISAKOS : joint disorders & orthopaedic sports medicine",authors:"Rüter ML, Kösters C, den Toom DA",design:"Studio monocentrico retrospettivo su dati raccolti prospetticamente (Maria-Josef-Hospital, Greven): pazienti consecutivi trattati con uno o due impianti Episealer (Episurf, Stoccolma) per lesioni focali (osteo)condrali del femore distale quando la riparazione biologica è fallita o improbabile; follow-up medio 38 mesi. KOOS, dolore VAS, eventi avversi e conversioni a UKA o TKA. Solo abstract letto.",pop:"93 pazienti di mezza età (45 con un impianto, 48 con due; calcolo mio). Età media, sesso, sede delle lesioni e numero di conversioni: non riportati nell'abstract. Conflitti d'interesse non riportati nell'abstract.",results:"KOOS sintomi da 48,7 ± 17,9 a 74,3 ± 21,6 (un impianto) e da 44,7 ± 15,0 a 66,0 ± 24,8 (due); miglioramento di tutte le sottoscale KOOS e del dolore VAS (p<0,001 in entrambi i gruppi); lieve vantaggio nel gruppo con un impianto. Sopravvivenza di Kaplan-Meier a 60 mesi: 88,1% (21 a rischio) e 83,4% (27 a rischio). IC non riportati.",concl:"Gli autori: i mini-impianti metallici su misura possono essere un'opzione per pazienti di mezza età quando la riparazione biologica non è praticabile, con sopravvivenza accettabile qualunque sia il numero di lesioni.",limits:"Nessun gruppo di confronto (microfrattura, AMIC, UKA) · follow-up medio 38 mesi, ma a 60 mesi restano 21 e 27 pazienti a rischio · punteggi prima/dopo senza controllo · IC della sopravvivenza e numero di conversioni non riportati · è sostituzione parziale con metallo, non cartilagine biologica.",perte:"Alternativa ad AMIC e AutoCart solo quando la riparazione biologica è fallita o improbabile: qui si sostituisce, non si rigenera. Per la tua pratica conta come opzione di salvataggio in pazienti di mezza età. Il dato è a medio termine e senza confronto con una riparazione biologica o con una UKA; non cambia le indicazioni a AMIC."},
{n:7,mono:"m-gray",dot:"gray",sec:"res",j:"Adv Sci",h:"Innesto di cartilagine ialina ingegnerizzata decellularizzata: primo impiego sull'uomo in 17 pazienti",v:"Studio clinico prospettivo esplorativo, primo impiego sull'uomo (City University of Hong Kong e altri centri; tre registrazioni ChiCTR): innesto di cartilagine ialina ingegnerizzata decellularizzata (dLhCG, matrice di collagene di tipo II) in 17 pazienti con difetti condrali a tutto spessore del ginocchio (Outerbridge III/IV). Integrazione stabile con il tessuto nativo fino a 18 mesi; miglioramento significativo dei punteggi clinici e del MOCART; rapporto T2 fra tessuto di riparazione e cartilagine sana vicino a 1; nessun evento avverso clinico grave, ma anomalie asintomatiche alla RM, fra cui edema osseo, in alcuni casi. Valori numerici e intervalli non riportati nell'abstract.",ax:"Zhang, Cheng, Fei, Liang, Zhang, Liu, Dai, Cong, Hu, Wu, Zhang, Cui, Yao, Wang, Wang, Sun, Zheng",date:"ott 2026",meta:"studio prospettivo esplorativo first-in-human, 17 pazienti, dLhCG nel ginocchio, 18 mesi · [livello IV per disegno, nessun controllo]",pmid:'42866965',doi:'10.1002/advs.202523106',journal:"Advanced science (Weinheim, Baden-Wurttemberg, Germany)",authors:"Zhang Z, Cheng G, Fei W, Liang Q, Zhang L, Liu K, Dai J, Cong B, Hu X, Wu Z, Zhang J, Cui J, Yao H, Wang DA, Wang J, Sun T, Zheng J",design:"Studio clinico prospettivo, esplorativo, first-in-human (ChiCTR2400094194, ChiCTR2500100526, ChiCTR2500105847): impianto di dLhCG in difetti articolari del ginocchio a tutto spessore (Outerbridge III/IV). Esiti: punteggi clinici, MOCART, mappatura T2 della RM (rapporto fra tessuto riparato e cartilagine adiacente sana), eventi avversi; osservazione fino a 18 mesi. Solo abstract letto.",pop:"17 pazienti con difetti condrali del ginocchio Outerbridge III/IV. Età, sede e dimensione dei difetti, punteggi usati e numero di pazienti con ciascun follow-up: non riportati nell'abstract.",results:"Integrazione stabile fino a 18 mesi; miglioramento significativo di punteggi clinici e MOCART; rapporto T2 tessuto riparato/cartilagine sana vicino a 1; nessun evento avverso clinico grave; anomalie asintomatiche alla RM, fra cui edema osseo. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: prove preliminari di fattibilità, sicurezza a breve termine ed esiti incoraggianti per una riparazione di tipo ialino; servono studi clinici controllati.",limits:"17 pazienti, nessun controllo (microfrattura, AMIC) · 18 mesi · «significativo» senza numeri nell'abstract · il rapporto T2 «vicino a 1» è un surrogato di imaging, non un esito del paziente · edema osseo asintomatico da seguire.",perte:"Non è AMIC né minced cartilage: è un innesto ingegnerizzato di matrice decellularizzata, qui solo in uno studio esplorativo senza controlli. Da guardare come direzione del campo, non come opzione. Il segnale da seguire nei lavori successivi è l'edema osseo asintomatico."},
{n:8,mono:"m-gray",dot:"gray",sec:"res",j:"Arthroplast Today",h:"Risurfacciamento rotuleo di routine: tutte le 22 lesioni peripatellari operate sono nel gruppo risurfacciato",v:"Coorte retrospettiva di una pratica singola ad alto volume (New Jersey): 3383 protesi totali primarie consecutive, giugno 2023-aprile 2025; 2508 con risurfacciamento rotuleo di routine, 875 senza. Lesioni peripatellari operate: 22 su 2508 (0,88%; IC 95% 0,55-1,33) contro 0 su 875 (0%; IC 95% 0-0,42); differenza assoluta 0,88 punti (p=0,002); OR di Firth 15,85 (IC 95% 2,20-2013,54; p=0,0015). Nessuna frattura rotulea operata. Revisioni complessive non valutate.",ax:"Dundon, Lewis, Brown, Phillips, Lombardi",date:"ott 2026",meta:"coorte retrospettiva monocentrica, 3383 protesi totali, rotula risurfacciata contro no · [livello III per disegno]",pmid:'42861386',doi:'10.1016/j.artd.2026.102169',journal:"Arthroplasty today",authors:"Dundon JM, Lewis S, Brown N, Phillips M, Lombardi P",design:"Coorte retrospettiva di una pratica singola ad alto volume (Orthopedic Research Institute of New Jersey, Chester; Morristown Medical Center): 3383 protesi totali primarie consecutive, giugno 2023-aprile 2025. Dati su chirurgo, risurfacciamento di routine e tipo di intervento peripatellare. Test esatto di Fisher; regressione di Firth per l'assenza di eventi in un gruppo. Assegnazione non randomizzata; confondenti (chirurgo, impianto) non descritti nell'abstract. Solo abstract letto.",pop:"3383 protesi totali primarie: 2508 con rotula risurfacciata, 875 senza. Età, sesso, impianto e follow-up: non riportati nell'abstract.",results:"Lesioni peripatellari operate: 22/2508 (0,88%; IC 95% 0,55-1,33) contro 0/875 (0%; IC 95% 0-0,42); differenza assoluta 0,88 punti (p=0,002); OR di Firth 15,85 (IC 95% 2,20-2013,54; p=0,0015). Nessuna frattura rotulea operata.",concl:"Gli autori: le lesioni peripatellari operate si sono osservate solo nelle rotule risurfacciate; l'associazione è significativa ma l'evento è raro, e servono dati a lungo termine sulle revisioni complessive.",limits:"Non randomizzato, un'unica pratica · follow-up non riportato nell'abstract · zero eventi in un braccio: l'OR di Firth ha un IC enorme (da 2,20 a 2013,54) · l'esito è un intervento peripatellare, non tutte le complicanze né le revisioni · la scelta di risurfacciare può correlare con paziente o chirurgo.",perte:"Non riguarda la tua protesi in sé (robotica, VELYS) ma la scelta se risurfacciare la rotula. Dato osservazionale di una sola pratica, evento raro e a breve termine: non basta per cambiare la scelta, aggiunge un'osservazione sul lato dei rischi del risurfacciamento. Cosa fare: nulla di nuovo."},
{n:9,mono:"m-gray",dot:"gray",sec:"res",j:"Bone Jt Open",h:"Due protesi totali a 15 anni: stessi esiti riferiti e sopravvivenza, più dolore anteriore con Kinemax",v:"Follow-up minimo di 15 anni di un RCT (Edimburgo): protesi totale primaria Kinemax contro Triathlon. Nove revisioni (sei asettiche, tre settiche), nessuna differenza fra i gruppi (p=0,721, log-rank); mortalità 50,7% (IC 95% 44,1-57,3), senza differenza (p=0,603). Valutazione funzionale in 61 pazienti (età media 80 anni): nessuna differenza in OKS, FJS, EQ-5D, EQ VAS e soddisfazione (p≥0,170). Con Kinemax più dolore anteriore (OR 3,2; p=0,037), linee radiotrasparenti tibiali in zona 1 (OR 12,1; IC 95% 2,6-57,6) e artrosi femororotulea grave (OR 5,1; IC 95% 1,4-18,4).",ax:"Clement, Williamson, Leitch, Scott, Gaston",date:"ott 2026",meta:"follow-up a 15 anni di RCT, due disegni di protesi totale, 61 valutati · [RCT, livello non dichiarato nell'abstract]",pmid:'42869432',doi:'10.1302/2633-1462.710.BJO-2026-0115.R1',journal:"Bone & joint open",authors:"Clement ND, Williamson TR, Leitch GL, Scott CEH, Gaston P",design:"Follow-up minimo di 15 anni di un RCT su protesi totale primaria con impianto Kinemax o Triathlon (Edinburgh Orthopaedics). Confronto di sopravvivenza (log-rank), mortalità, PROM (Oxford Knee Score, Forgotten Joint Score, EQ-5D, EQ VAS), sede e intensità del dolore, radiografie. Solo abstract letto.",pop:"61 pazienti alla valutazione funzionale a 15 anni (età media 80 anni, DS 8,5; 41 donne, 67%). Numero dei randomizzati e ripartizione fra i due gruppi: non riportati nell'abstract. 108 decessi.",results:"Nove revisioni (sei asettiche, tre settiche), p=0,721 (log-rank); mortalità a 15 anni 50,7% (IC 95% 44,1-57,3), p=0,603. OKS, FJS, EQ-5D, EQ VAS e soddisfazione senza differenze (p≥0,170). Dolore anteriore con Kinemax OR 3,2 (p=0,037); linee radiotrasparenti tibiali zona 1 OR 12,1 (IC 95% 2,6-57,6); artrosi femororotulea grave OR 5,1 (IC 95% 1,4-18,4; p=0,010). Nessun allentamento.",concl:"Gli autori: i due impianti danno PROM comparabili, che peggiorano nel tempo ma restano migliori del preoperatorio; Kinemax ha più dolore anteriore, senza differenze clinicamente rilevanti negli esiti.",limits:"Solo 61 valutati funzionalmente: sopravvissuti, età media 80 anni · nove revisioni in tutto e ripartizione non riportata: la sopravvivenza non può dire molto · confronti multipli sulle radiografie, IC larghi · due impianti di una sola epoca · non sono impianti robotici.",perte:"Protesi totale generica, non robotica né VELYS. Il valore sta nel follow-up lungo e nel messaggio sulla femororotulea: il disegno dell'impianto sposta dolore anteriore e artrosi femororotulea anche quando punteggi e sopravvivenza sono uguali. Non cambia la tua pratica; è un argomento in più sulla scelta del disegno femorale."}];
var SUGGQ=[{"k": "kol", "n": "Jorge Chahla (Rush University Medical Center, Chicago, USA)", "w": "Stati Uniti: ultimo firmatario della serie di casi di oggi sul pie-crusting del collaterale mediale nella rifissazione della radice del menisco mediale (PMID 42865127; afferenza letta nei metadati PubMed). Corrispondenza tecnica diretta con la tua rifissazione della radice mediale. Sostituisce Thomas Ripoll (13 ottobre, nessun segnale dell'utente arrivato per farla ruotare)."}];
var BRIEF_TEXT="Mercoledì 14 ottobre. Oggi nove lavori, nessuna scheda rossa e nessuna arancione: nessun richiamo di dispositivi nuovo, nessuna ritrattazione che ti riguardi, nessun nuovo consensus o linea guida nella tua pratica. Il lavoro del giorno tocca la tua chirurgia del menisco: una serie di casi di Chicago, ventuno rifissazioni della radice posteriore del menisco mediale con pie-crusting spinto del collaterale mediale. Circa sei mesi dopo, alle radiografie da stress in valgo, la differenza con il lato sano è in media di un millimetro e due decimi, intervallo di confidenza da 0,73 a 1,70, sotto la soglia di tre millimetri e due decimi della lassità clinicamente rilevante. È una serie piccola, senza gruppo di confronto, e l'abstract non riporta esiti clinici né guarigione della radice. Poi tre lavori sul crociato. Un'analisi secondaria di un trial su cinquecento operati con hamstring, con o senza rinforzo laterale: le atlete hanno odds di tornare a sport ad alto rischio pari a 0,47 volte quelle degli uomini, e meno di uno su due torna a sport e livello di prima. Il registro svedese su oltre diecimila calciatori: il cinquantotto e mezzo per cento torna in partita, ma dopo il rientro si gioca poco. Infine uno studio sulla forza del quadricipite in cinquantanove operati: nel cinquantuno per cento la forza è bassa da entrambi i lati e non c'è legame con il KOOS né con la cartilagine a un anno, ma lo studio è troppo piccolo per escluderlo. Poi un punteggio diagnostico per il menisco laterale ipermobile, validato solo internamente, e quattro lavori fuori dalla tua tecnica: mini-impianti metallici su misura nel femore, un innesto di cartilagine decellularizzata al primo impiego sull'uomo, il risurfacciamento rotuleo nella protesi totale e il follow-up a quindici anni di due protesi totali. Nella seconda pagina trovi dodici brevi e tre proposte fuori dal solito.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Mercoledì quattordici ottobre. Nove lavori, nessuna scheda rossa e nessuna arancione. Nessun richiamo nuovo, nessuna ritrattazione che ti riguardi, nessun consensus nella tua pratica."}, {"chi": "B", "t": "Quindi il lavoro del giorno?"}, {"chi": "A", "t": "Tocca la tua chirurgia del menisco. Una serie di Chicago su ventuno rifissazioni della radice posteriore del menisco mediale, con pie-crusting spinto del collaterale mediale."}, {"chi": "B", "t": "E la domanda è se il legamento resta stabile."}, {"chi": "A", "t": "Esatto. A circa sei mesi, alle radiografie da stress in valgo, il ginocchio operato si apre in media un millimetro e due decimi più del sano, contro una soglia di tre millimetri e due decimi per la lassità che conta."}, {"chi": "B", "t": "Quindi per la tua rifissazione transtibiale il gesto non lascia un problema di stabilità."}, {"chi": "A", "t": "Con un limite chiaro: ventuno casi, nessun confronto con un pie-crusting più leggero, e l'abstract non dice nulla su sintomi né su guarigione della radice."}, {"chi": "B", "t": "Poi il crociato."}, {"chi": "A", "t": "Tre lavori. Un'analisi secondaria di un trial su cinquecento operati con hamstring: le atlete hanno odds di tornare a sport ad alto rischio pari a zero virgola quarantasette volte quelle degli uomini, e meno di uno su due torna a sport e livello di prima."}, {"chi": "B", "t": "Ma è hamstring, non il tuo retto femorale."}, {"chi": "A", "t": "Giusto, e il rinforzo laterale era randomizzato, mentre tu lo fai a tutti. Quello che vale è la dimensione del problema nel rientro."}, {"chi": "B", "t": "E gli altri due?"}, {"chi": "A", "t": "Il registro svedese: oltre diecimila calciatori, il cinquantotto e mezzo per cento torna in partita, ma dopo il rientro si gioca poco. E uno studio su cinquantanove operati dove nel cinquantuno per cento la forza del quadricipite è bassa da entrambi i lati."}, {"chi": "B", "t": "Quindi un criterio di rientro basato sulla simmetria poggia su un denominatore che scende."}, {"chi": "A", "t": "Sì, ma attenzione: con cinquantanove pazienti lo studio non può escludere un legame con gli esiti. Il resto della giornata è fuori dalla tua tecnica, e nella seconda pagina trovi dodici brevi e tre proposte fuori dal solito."}];
